elif op[0] == "br":
    # 全池运行态快照：除共用时钟按 now 推进外不改任何运行态，失败
    # 批次天然回滚。backends 按加入序，项键序
    # id,health,circuit,drain,fault,connections,ready,blocked。
    # fault 取 fq 同款 effect（N/D/S）；ready 要求 healthy、熔断
    # C（含未配）、排空 A 且 fault≠D（S 不阻断）；blocked 按
    # health,circuit,drain,fault 顺序列出未满足项，ready 时为空。
    # 活动段查找为 O(log T_b)，整体时间 O(B log(T+1))、空间 O(B)。
    _, now = op
    snapshot = []
    for backend_id, record in backends.items():
        circuit = record["circuit"]
        circuit_state = (
            "C" if circuit is None else circuit["state"]
        )
        drain_state = record["drain"]["state"]
        effect = fault_effect(active_fault(record, now), now)
        blocked = []
        if not record["healthy"]:
            blocked.append("health")
        if circuit_state != "C":
            blocked.append("circuit")
        if drain_state != "A":
            blocked.append("drain")
        if effect == "D":
            blocked.append("fault")
        snapshot.append(
            {
                "id": backend_id,
                "health": (
                    "healthy" if record["healthy"] else "unhealthy"
                ),
                "circuit": circuit_state,
                "drain": drain_state,
                "fault": effect,
                "connections": record["conns"],
                "ready": not blocked,
                "blocked": blocked,
            }
        )
    results.append({"op": "br", "now": now, "backends": snapshot})

elif op[0] == "ru":
    # 不可用时长查询：除共用时钟按 now 推进（批前通用时钟块）外只读，
    # 失败批次天然回滚。reasons 按 drain,health,circuit,fault 排序，
    # 项键序 reason,since,duration，duration=now-since。health/drain/
    # circuit 取各转换点维护的连续生效起点；fault 只读时间线：D 段
    # since=a，F 下线相位 since=a+2*v*((now-a)//(2*v))，S 不列入。
    # 活动段查找 O(log T_b)，整体时间 O(log(T+1))、空间 O(1)。
    _, backend_id, now = op
    record = backends.get(backend_id)
    if record is None:
        fail(EXIT_BACKEND, "BACKEND")
    since_map = record["unavail_since"]
    reasons = []
    drain_since = since_map["drain"]
    if drain_since is not None:
        reasons.append(
            {
                "reason": "drain",
                "since": drain_since,
                "duration": now - drain_since,
            }
        )
    health_since = since_map["health"]
    if health_since is not None:
        reasons.append(
            {
                "reason": "health",
                "since": health_since,
                "duration": now - health_since,
            }
        )
    circuit_since = since_map["circuit"]
    if circuit_since is not None:
        reasons.append(
            {
                "reason": "circuit",
                "since": circuit_since,
                "duration": now - circuit_since,
            }
        )
    segment = active_fault(record, now)
    if segment is not None:
        kind, seg_a, _, seg_v = segment
        if kind == "D":
            # 整个 D 段均不可用。
            fault_since = seg_a
        elif kind == "F" and ((now - seg_a) // seg_v) % 2 == 0:
            # F 下线相位：[a+2jv, a+(2j+1)v)，相位起点对齐到偶数 v。
            fault_since = seg_a + 2 * seg_v * (
                (now - seg_a) // (2 * seg_v)
            )
        else:
            # F 上线相位与 S（仅变慢）均不阻断。
            fault_since = None
        if fault_since is not None:
            reasons.append(
                {
                    "reason": "fault",
                    "since": fault_since,
                    "duration": now - fault_since,
                }
            )
    results.append(
        {"op": "ru", "id": backend_id, "now": now, "reasons": reasons}
    )

